def longest_orf(s, name):
    best = (0,0,0,0,0)  # len, start, end, frame, name
    for frame in range(3):
        # segment into codons, find runs without stop
        start = None
        for j in range(frame, len(s)-2, 3):
            cod = s[j:j+3]
            if cod in ("TAA","TAG","TGA"):
                if start is not None:
                    L = j - start
                    if L > best[0]:
                        best = (L, start, j, frame, name)
                start = None
            else:
                if start is None:
                    start = j
    return best

