seq = "".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
n=len(seq)
comp=str.maketrans("ACGT","TGCA")
rc=seq.translate(comp)[::-1]

# Proper ORFs: ATG ... in-frame stop, no internal stop, min 100 nt
def find_orfs(s, strand):
    out=[]
    stops=set()
    for frame in range(3):
        i=frame
        while i < len(s)-2:
            if s[i:i+3]=="ATG":
                j=i
                while j < len(s)-2 and s[j:j+3] not in ("TAA","TAG","TGA"):
                    j+=3
                L=j-i
                if L>=90:
                    out.append((i,j,L,strand,frame))
                i+=3
            else:
                i+=3
    return out

orf = find_orfs(seq,"+")+find_orfs(rc,"-")
orf.sort(key=lambda x:-x[2])
print("longest ATG-initiated stop-free ORFs:")
for o in orf[:8]:
    i,j,L,st,fr=o
    if st=="+":
